import csv
import io

def parse_csv(raw_csv: str):
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    reader = csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
        strict=False
    )

    records = []
    try:
        for record in reader:
            if record:
                records.append(record)
    except csv.Error:
        pass

    expected_width = 9
    header_count = 3
    header_start = None

    for i in range(0, max(0, len(records) - header_count)):
        header_records = records[i:i + header_count]
        if sum(len(row) for row in header_records) != expected_width:
            continue
        following = records[i + header_count:]
        if following and len(following[0]) == expected_width:
            header_start = i
            break

    if header_start is None:
        first_full = None
        for i, row in enumerate(records):
            if len(row) == expected_width:
                first_full = i
                break
        if first_full is not None and first_full >= header_count:
            header_start = first_full - header_count
        elif len(records) >= header_count:
            header_start = 0
        else:
            header_start = len(records)

    header_records = records[header_start:header_start + header_count]
    columns = []
    for row in header_records:
        columns.extend(row)

    if not columns:
        columns = ["column_{}".format(i + 1) for i in range(expected_width)]

    if len(columns) < expected_width:
        columns.extend(
            "column_{}".format(i + 1)
            for i in range(len(columns), expected_width)
        )
    elif len(columns) > expected_width:
        columns = columns[:expected_width - 1] + [
            ",".join(columns[expected_width - 1:])
        ]

    rows = []
    for row in records[header_start + header_count:]:
        if len(row) < expected_width:
            row = row + [""] * (expected_width - len(row))
        elif len(row) > expected_width:
            row = row[:expected_width - 1] + [
                ",".join(row[expected_width - 1:])
            ]
        rows.append(row)

    return {"columns": columns, "rows": rows}
